import numpy as np
from scipy.optimize import least_squares
def run(basis,k0s):
    def resid(p):
        X=basis(p)
        c,_,_,_=np.linalg.lstsq(X,dP_dt,rcond=None)
        return dP_dt-X@c
    best=None
    for k0 in k0s:
        s=least_squares(lambda p: resid(p), [k0])
        if best is None or s.cost<best.cost: best=s
    return best.x, np.mean(best.fun**2)/np.var(dP_dt)
